import React from "react";
import ReactDOM from "react-dom/client";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { HashRouter } from "react-router-dom";

import { App } from "./app/App";
import { BackendProvider } from "./backend/BackendProvider";
import { ThemeProvider } from "./app/theme/ThemeProvider";

import "./app/theme/tokens.css";
import "./styles/globals.css";

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 15_000,
      retry: 1
    }
  }
});

ReactDOM.createRoot(document.getElementById("root")!).render(
  <React.StrictMode>
    <QueryClientProvider client={queryClient}>
      <BackendProvider>
        <ThemeProvider>
          <HashRouter>
            <App />
          </HashRouter>
        </ThemeProvider>
      </BackendProvider>
    </QueryClientProvider>
  </React.StrictMode>
);

import { Navigate, Route, Routes } from "react-router-dom";

import { AppShell } from "./shell/AppShell";
import { moduleRegistry } from "./modules/registry";

export function App() {
  const routes = moduleRegistry.getRoutes();

  return (
    <AppShell>
      <Routes>
        <Route path="/" element={<Navigate to="/projects" replace />} />

        {routes.map((route) => {
          const Component = route.component;

          return (
            <Route
              key={route.path}
              path={route.path}
              element={<Component />}
            />
          );
        })}

        <Route path="*" element={<Navigate to="/projects" replace />} />
      </Routes>
    </AppShell>
  );
}

import type { ComponentType } from "react";
import type { LucideIcon } from "lucide-react";

export interface ModuleRoute {
  path: string;
  component: ComponentType;
}

export interface NavigationItem {
  id: string;
  label: string;
  route: string;
  icon: LucideIcon;
  order?: number;
}

export interface MissionControlModule {
  id: string;
  name: string;
  routes?: ModuleRoute[];
  navigation?: NavigationItem[];
}

import type {
  MissionControlModule,
  ModuleRoute,
  NavigationItem
} from "./types";

import { projectsModule } from "../../modules/projects/module";
import { settingsModule } from "../../modules/settings/module";

class ModuleRegistry {
  private readonly modules = new Map<string, MissionControlModule>();

  register(module: MissionControlModule) {
    if (this.modules.has(module.id)) {
      throw new Error(`Mission Control module already registered: ${module.id}`);
    }

    this.modules.set(module.id, module);
  }

  getModules(): MissionControlModule[] {
    return [...this.modules.values()];
  }

  getRoutes(): ModuleRoute[] {
    return this.getModules().flatMap((module) => module.routes ?? []);
  }

  getNavigationItems(): NavigationItem[] {
    return this.getModules()
      .flatMap((module) => module.navigation ?? [])
      .sort((a, b) => (a.order ?? 100) - (b.order ?? 100));
  }
}

export const moduleRegistry = new ModuleRegistry();

moduleRegistry.register(projectsModule);
moduleRegistry.register(settingsModule);

import type { ReactNode } from "react";
