  flex-direction: column;
  padding: 16px 12px;
  border-right: 1px solid var(--mc-border-subtle);
  background: var(--mc-sidebar);
}

.mc-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 40px;
  padding: 0 8px;
  margin-bottom: 18px;
}

.mc-brand-mark {
  display: grid;
  place-items: center;
  width: 29px;
  height: 29px;
  border: 1px solid var(--mc-border);
  border-radius: var(--mc-radius-md);
  background: var(--mc-surface-raised);
  color: var(--mc-accent);
