  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.mc-page-header h1 {
  margin: 0;
  font-size: 25px;
  font-weight: 650;
  letter-spacing: -0.035em;
}

.mc-page-description {
  max-width: 560px;
  margin: 8px 0 0;
  color: var(--mc-text-secondary);
  line-height: 1.55;
}

.mc-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 34px;
  padding: 0 12px;
  border: 1px solid var(--mc-border);
  border-radius: var(--mc-radius-sm);
  background: var(--mc-surface-raised);
  cursor: pointer;
}

.mc-button-primary {
  border-color: transparent;
  background: var(--mc-accent);
  color: white;
}

.mc-toolbar {
  display: flex;
  margin-bottom: 14px;
}

.mc-search {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 320px;
  height: 34px;
  padding: 0 10px;
  border: 1px solid var(--mc-border);
  border-radius: var(--mc-radius-sm);
  background: var(--mc-surface);
  color: var(--mc-text-muted);
}

.mc-search input {
  width: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--mc-text-primary);
}

.mc-panel {
  border: 1px solid var(--mc-border);
  border-radius: var(--mc-radius-md);
  background: var(--mc-surface);
}

.mc-project-empty {
  display: flex;
  min-height: 360px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
