}

.mc-section-heading {
  margin-bottom: 16px;
}

.mc-section-heading h2 {
  margin: 0;
  font-size: 14px;
  font-weight: 650;
}

.mc-section-heading p {
  margin: 5px 0 0;
  color: var(--mc-text-secondary);
  font-size: 13px;
