.mc-theme-choice {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  min-height: 92px;
  padding: 15px;
  border: 1px solid var(--mc-border);
  border-radius: var(--mc-radius-md);
  background: var(--mc-surface);
  text-align: left;
  cursor: pointer;
}

.mc-theme-choice:hover {
  background: var(--mc-surface-hover);
}

.mc-theme-choice.is-selected {
  border-color: var(--mc-accent);
  box-shadow: inset 0 0 0 1px var(--mc-accent);
}

.mc-theme-choice svg {
  margin-top: 1px;
  color: var(--mc-text-secondary);
}

.mc-theme-choice.is-selected svg {
  color: var(--mc-accent);
}

.mc-theme-choice span {
  display: flex;
  flex-direction: column;
}

.mc-theme-choice strong {
  font-size: 13px;
  font-weight: 620;
}

.mc-theme-choice small {
  margin-top: 5px;
  color: var(--mc-text-secondary);
  font-size: 11px;
  line-height: 1.45;
}

@media (max-width: 900px) {
